import hashlib, bisect

VIRTUAL_NODES = 128

class CacheRing:
    def __init__(self):
        self.ring = []  # (position, node_id)
        self.nodes = set()

    def _pos(self, s: str) -> int:
        return int(hashlib.md5(s.encode()).hexdigest(), 16)

    def add_node(self, node_id: str):
        self.nodes.add(node_id)
        for i in range(VIRTUAL_NODES):
            p = self._pos(f"{node_id}#{i}")
            self.ring.append((p, node_id))
        self.ring.sort()

    def remove_node(self, node_id: str):
        self.nodes.discard(node_id)
        self.ring = [(p, n) for p, n in self.ring if n != node_id]

    def primary(self, key: str) -> str:
        h = self._pos(key)
        idx = bisect.bisect(self.ring, (h, ""))
        if idx == len(self.ring):
            idx = 0  # wrap around the ring
        return self.ring[idx][1]

    def replicas(self, key: str, r: int = 3):
        # Next r-1 distinct nodes clockwise from primary.
        h = self._pos(key)
        idx = bisect.bisect(self.ring, (h, ""))
        out, seen = [], set()
        i = idx
        while len(out) < r and self.ring:
            _, n = self.ring[i % len(self.ring)]
            if n not in seen:
                seen.add(n)
                out.append(n)
            i += 1
        return out
